import json, hashlib
from pathlib import Path
from PIL import Image
R=Path(__file__).resolve().parents[1]
date='2026-10-22'
def save(path,data):
    (R/path).parent.mkdir(parents=True,exist_ok=True)
    (R/path).write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
sources=[]
def source(id,url,path,summary):
    sources.append(dict(id=id,url=url,accessedAt=date,locator=summary,summary=summary,evidencePath=path,fingerprint=hashlib.sha256((R/path).read_bytes()).hexdigest()))
notes='''# Source observations, 2026-10-22
Official Instagram https://www.instagram.com/bumiupi/ opened in Chrome. Profile says Rumah Tamah, Garut Jawa Barat, every day 07:00-23:00, bio links https://linktr.ee/bumiupi. Website does not claim to be official.
Linktree title Bumi Upi Rumah Tamah. Three relevant buttons: Maps (Jl. Cimanuk No.312, Pataruman, Tarogong Kidul, Garut 44150), Menu Sarapan, Menu Reguler. Both PDFs downloaded and all six pages rendered and visually read; no embedded text, each page is one raster. Products transcribed manually and cropped; raw files archived with hashes. PDF font names cannot establish a web font: Archivo Black open-license is a close heavy sans substitute; DM Sans open-license for controls/body. Logo is an original raster crop, never recreated with text.
Social links: Instagram profile inspected; WhatsApp link opened only to read destination https://api.whatsapp.com/send?phone=62895412055152, no message sent. TikTok social content is supplementary and not required for menu data; no login performed.
PDF note: prasmanan and special daily menu available; ask cashier/pramusaji, no fabricated daily SKU/price. Shared breakfast/reguler dishes are deduplicated. Roti Bakar Kornet Keju: reguler 22rb, sarapan 26rb, both contextual variants preserved. Burger Original 27rb is separate from Burger Gulai 30rb. Duplicate Dimsum Ekonomis retained temporarily in transcription then deduplicated in runtime reconciliation. PDF prices supported by accessible official sources, not reconfirmed with owner for today's sale.
Instagram recent posts contain bank-bjb campaign and match promo; snapshot AX caption differs from visible match poster, so specific date/opponent/terms are omitted rather than treating accessibility text as conclusive. Current activities are discoverable through Instagram footer. Photobooth existence cross-checked with official linked Maripoto reel https://www.instagram.com/maripoto.id/reel/Ddbn-FAx_ii/ ; no unverified booth price displayed. No unsupported capacity, rating, Wi-Fi, parking, event-package or review claim.
Asset discovery: Chrome Google Images search Bumi Upi Garut opened; source pages found including Momopururu first-person visit. Full source https://momopururu.com/kuliner/bumi-upi-garut/ downloaded, original full-size files retrieved. Exterior, indoor, courtyard, booth matched by captions and visuals, watermark retained intact. All rights pending, local concept only. Blog body not copied. Other candidate photographs 11/06 not used because same room/people repeated; 11 added to the atmosphere mosaic; 32 rejected because it foregrounds the visiting family. Menu pictures used for matching products, no stock/AI substitution.
Official Instagram grid inspected but recent assets largely campaign posters/reels/people; no Instagram downloader used because complete product imagery is already present in the two official downloadable PDFs and source photography meets local atmosphere coverage. GoFood discovery search returned no reliably matched merchant; Bumi Cafe Cimanuk is a different business, excluded.
Layout alternatives: A split photographic entrance -> three-room mosaic -> photo rows catalogue -> booth -> visit; B typographic menu first -> compact rows -> single story photo -> visit. A chosen because original facade and room photos communicate Rumah Tamah before many menu entries. B rejected because it loses the destination atmosphere. Mobile keeps text/CTA before facade, scenes stacked, one catalogue column. No decorative pills, no overlines, no auto-running carousel. Motion entrance/reveal/search expansion and select state; reduced motion supported.
Component provenance: local copies of official shadcn registry components Button/Input/Select from Historia components/ui; Base UI primitive, cva and cn unchanged. No entire page copied. All dependencies explicitly declared in standalone demos/bumi-upi package.
Coverage: name, address, hours, contact -> hero/visit. All unique PDF dishes -> catalogue; shared duplicate products deduplicated, size/context variants preserved. Prasmanan/special daily dishes -> kitchen note. Photobooth -> together. Instagram -> footer for recent activities. Testimonials omitted: no reliable independently attributable quote collected. Prices/asset rights not owner-approved. No publication, deployment, or outreach authorized.
'''
(R/'research/sources.md').write_text(notes,encoding='utf-8')
source('profile','https://www.instagram.com/bumiupi/','research/sources.md','Chrome official profile: Rumah Tamah; Garut; daily 07.00-23.00; linked official bio hub.')
source('hub','https://linktr.ee/bumiupi','research/sources.md','Chrome bio hub: two PDF menus, address, Instagram, TikTok and verified WhatsApp destination.')
source('sarapan','https://ugc.production.linktr.ee/3b867c63-2791-46f3-ac53-1d5e1ea38437_MENU-SARAPAN.pdf','research/raw/sarapan.pdf','Official linked breakfast menu, 2 raster pages rendered and visually transcribed.')
source('reguler','https://ugc.production.linktr.ee/b757f7b3-1c06-45fd-ba3a-ec64b4ebe149_MENU-REGULER-BUMI-UPI.pdf','research/raw/reguler.pdf','Official linked regular menu, 4 raster pages rendered and visually transcribed.')
source('place','https://momopururu.com/kuliner/bumi-upi-garut/','research/raw/place.html','First-person visit May 2026 with original captioned exterior, indoor, courtyard and photobooth images. Rights pending; original watermark retained.')
source('booth','https://www.instagram.com/maripoto.id/reel/Ddbn-FAx_ii/','research/sources.md','Official Bumi Upi grid links Maripoto booth reel; caption confirms booth in Garut.')
source('fonts','https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Archivo+Black&display=swap','research/raw/fonts.css','Google Fonts open license typeface distributions; substitute hierarchy, not original brand webfonts.')
def fact(id,field,value,ids):return dict(id=id,field=field,value=value,sourceIds=ids,checkedAt=date,status='verified',used=True,limitation='Source-supported; not reconfirmed by owner.')
facts=[fact('name','name','Bumi Upi',['profile','hub']),fact('hours','hours','Setiap hari 07.00-23.00 WIB',['profile']),fact('address','address','Jl. Cimanuk No.312, Pataruman, Tarogong Kidul, Garut 44150',['hub']),fact('contact','contact','62895412055152',['hub']),fact('daily','daily_menu','Prasmanan dan menu spesial harian, tanyakan pramusaji',['reguler']),fact('photobooth','photobooth',True,['booth','place'])]
data=json.loads((R/'data/menu.json').read_text(encoding='utf-8')); seen=set();clean=[]
for i in data:
    if i['name'] in seen:continue
    seen.add(i['name']);clean.append(i)
save('data/menu.json',clean)
features={k:k in ['catalogue','categoryFilter','search','loadMore','location'] for k in ['catalogue','categoryFilter','search','stickyToolbar','loadMore','productDialog','carousel','accordion','location']}
signature=dict(hero='split-product',sequence='place-first',catalogue='photo-rows',media='mosaic',narrative='destination')
sections=[dict(id='hero',features=[]),dict(id='suasana',features=[]),dict(id='menu',features=['catalogue','categoryFilter','search','loadMore']),dict(id='together',features=[]),dict(id='kunjungi',features=['location'])]
plan=dict(prospectId='bumi-upi-garut',primaryGoal='Explore real menu and plan a visit or ask via official WhatsApp.',features=features,sections=sections,media=[],layoutSignature=signature,candidates=[dict(id='place-first',layoutSignature=signature,rationale='Authentic house facade and indoor/courtyard photography communicate Rumah Tamah; compact photo rows suit small PDF crop resolution.'),dict(id='menu-direct',layoutSignature=dict(hero='brand-typographic',sequence='product-first',catalogue='compact-rows',media='single-story-image',narrative='quick-visit'),rationale='Feasible with raster menus but rejected because it underrepresents the house and destination atmosphere.')],selectedCandidate='place-first',brand={'colors':['#faf4e7','#51582d','#a13223','#edbe50'],'type':'Archivo Black for heavy sans menu hierarchy, DM Sans body; weblicensed substitutes. Original logo raster.'},mobile='Hero text then facade, stacked room photographs, one column catalogue, inline expanding search.',componentProvenance='Official shadcn Button, Input, Select copied locally; Base UI behavior preserved.',contentCoverage=[dict(finding=s,sectionIds=[sec],sourceIds=ids) for s,sec,ids in [('identity and hours','hero',['profile']),('all unique PDF offerings and price variants','menu',['reguler','sarapan']),('daily specials note','menu',['reguler']),('photobooth','together',['booth','place']),('address and contact','kunjungi',['hub'])]],mediaCoverage={'productImages':len(clean),'products':len(clean),'placePhotos':5,'limitations':'Raster source crops are small; use compact thumbnails. Original source photographs retain watermark and pending rights. No AI food images.'})
plan['visualIdentity']=dict(confidence='medium',observations=[
dict(aspect='palette',sourceId='profile',evidencePath='research/raw/brand-feed.png',observation='Recurring olive grounds with cream uppercase text; campaigns add mustard and red, while partner sports posters use blue.',translation='Cream reading ground, olive CTA and full-width booth section, red headline accents and mustard frame. Partner blue excluded.'),
dict(aspect='typography',sourceId='reguler',evidencePath='research/raw/reguler-full-2.png',observation='MENU is broad block sans; category headings are dense bold sans, body is compact and rounded; wordmark has distinctive rounded strokes.',translation='Original wordmark image retained. Archivo Black broad low-contrast block strokes fit MENU/BERBAGI headlines better than Inter/Manrope; DM Sans handles small body and controls. Exact poster font is unknown.'),
dict(aspect='composition',sourceId='profile',evidencePath='research/raw/brand-feed.png',observation='Posters frame products and people with large compact headline blocks, cutout dishes and source color grounds.',translation='Split facade plus compact multi-line title, a three-photo room mosaic, and dense small catalogue photo rows rather than huge repeated cards.'),
dict(aspect='imagery',sourceId='reguler',evidencePath='research/raw/reguler-full-2.png',observation='Named dishes are isolated on patterned plates, set on paper; place sources show warm wood, vintage furniture and greenery.',translation='Keep exact plate crops for SKU, small enough for source resolution. Original warm facade and room photography, watermark retained, no stock food.'),
dict(aspect='graphicLanguage',sourceId='reguler',evidencePath='research/raw/reguler-full-2.png',observation='Four-petal wallpaper motif, paper texture, olive/mustard/red inset frames repeat through menu pages.',translation='Olive and mustard double frame on hero, source-cropped four-petal detail at kitchen note, restrained cream surfaces. No decorative pills or eyebrow labels.')],retained=['Original rounded wordmark, olive grounds, heavy sans title hierarchy and warm vintage imagery.','Retro inset-frame vocabulary and source four-petal motif.'],adapted=['Print texture simplified for reading; source frame retained as hero border.','Exact menu font not established; Archivo Black broad block shapes compared with official MENU and Instagram uppercase headlines.','Initial arch experiment replaced with source-led inset frame; room photos become mosaic on desktop and stack on mobile.'],avoidedDefaults=['No copied Historia full-width hero or featured carousel.','No giant typographic collage like Duduk Gembira, no all-category unbounded list like Talkie Space.','No generic arch masks; paper and frame treatment follows official menu.'])
assets=[]
def asset(id,path,sourceIds,subject,sectionIds,productIds=[],kind='image',rights='pending'):
    im=Image.open(R/path) if kind!='font' else None
    assets.append(dict(id=id,kind=kind,subject=subject,sourceIds=sourceIds,productIds=productIds,sectionIds=sectionIds,authenticity='verified',rightsStatus=rights,rightsEvidence=[],attribution='Bumi Upi official menu' if sourceIds==['reguler'] or sourceIds==['sarapan'] else 'Momopururu / Istiana Sutanti' if sourceIds==['place'] else 'Google Fonts',deliveryMethod='file',runtimePath=path,embedUrl=None,width=im.width if im else None,height=im.height if im else None))
    for sec in sectionIds:plan['media'].append(dict(assetId=id,productId=productIds[0] if productIds else None,sectionId=sec))
offerings=[]
def price(n,ids):return dict(amount=n,currency='IDR',checkedAt=date,sourceIds=ids)
for i in clean:
    ids=[i['source']]; ids=['reguler','sarapan'] if i['name']=='Roti Bakar Kornet Keju' else ids
    aid='image-'+i['id'];asset(aid,'public'+i['image'],[i['source']],i['name'],['menu'],[i['id']])
    offerings.append(dict(id=i['id'],name=i['name'],kind='product',category=i['category'],description=i['description'],sourceIds=ids,status='verified',price=price(i['price'],ids),promo=None,variants=[dict(id=i['id']+'-'+str(n),name=v['name'],price=price(v['price'],['sarapan'] if v['name']=='Sarapan' else ids)) for n,v in enumerate(i['variants'])],imageId=aid))
asset('logo','public/images/logo.webp',['reguler'],'Original Bumi Upi logo raster crop',['hero'])
asset('motif','public/images/motif.webp',['reguler'],'Original menu four-petal pattern crop',['menu'])
for id,sec in [('17','hero'),('16','suasana'),('02','suasana'),('07','together'),('11','suasana')]:asset('place-'+id,f'public/images/place-{id}.webp',['place'],'Bumi Upi photograph '+id,[sec])
for name in ['archivo-black','dm-sans']:asset(name,f'public/fonts/{name}.ttf',['fonts'],name,['hero'],kind='font',rights='licensed')
save('research-bundle.json',dict(schemaVersion=2,profile=dict(prospectId='bumi-upi-garut',name='Bumi Upi',branch=None,sources=sources,facts=facts),offerings=dict(items=offerings),assets=dict(items=assets),pagePlan=plan))
save('research/quality/page-plan.json',plan)
save('run-state.json',dict(prospectId='bumi-upi-garut',businessName='Bumi Upi',branch=None,stage='strategy',projectRoot=str(R),scope='Local independent concept demo',artifacts=['research-bundle.json','data/menu.json','research/contact-sheet.jpg'],decisions=['Place-first split hero with authentic facade photo','No simulated booking form','Both PDFs reconciled; contextual price difference retained'],openIssues=['Photo rights pending','Prices not reconfirmed by owner'],authorization={'localDemo':'buatkan demo untuk cafe/resto bumi upi di garut','push':False,'deploy':False,'send':False},sourceFingerprints={s['id']:s['fingerprint'] for s in sources},lastUpdated=date))
print(len(clean),'unique offerings,',len(assets),'assets')


